 trueksort
 arrayarray
 intflagsSORT_REGULAR



 Ordina array sul posto per chiave
 in ordine crescente.

&note.sort-unstable;
&note.reset-index;

&reftitle.changelog;







     &Version;
     &Description;



    &return.type.true;


     8.2.0

      Questa funzione ora effettua il confronto delle stringhe numeriche con
      SORT_REGULAR usando le regole standard di PHP 8.

  &reftitle.examples;



    Esempio di ksort


<?php
$fruits = array("d"=>"limone", "a"=>"arancia", "b"=>"banana", "c"=>"mela");
ksort($fruits);
foreach ($fruits as $key => $val) {
    echo "$key = $val\n";
}
?>


    &example.outputs;


a = arancia
b = banana
c = mela
d = limone








    ksort con chiavi int


<?php
$a = [0 => 'Primo', 2 => 'Ultimo', 1 => 'Medio'];
var_dump($a);
ksort($a);
var_dump($a);
?>


    &example.outputs;


array(3) {
  [0]=>
  string(5) "Primo"
  [2]=>
  string(6) "Ultimo"
  [1]=>
  string(5) "Medio"
}
array(3) {
  [0]=>
  string(5) "Primo"
  [1]=>
  string(5) "Medio"
  [2]=>
  string(6) "Ultimo"
}
